package com.unilinker.android.mediatier

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Test
import java.util.Base64

/**
 * Cross-language conformance: the fixture was generated by the Windows
 * sender (tests/UniLinker.Core.Tests/DirectRtpChannelTests.cs, fixed
 * key/salt, deterministic AU) — these JVM tests prove the Android receiver
 * chain (jitsi-srtp unprotect → FU-A/STAP-A reassembly) reproduces the
 * exact original Annex-B access unit. Runs without a device.
 */
@Serializable
data class DirectRtpFixture(
    val masterKeyB64: String,
    val masterSaltB64: String,
    val cryptoLine: String,
    val ssrc: Long,
    val annexBAuB64: String,
    val timestampUs: Long,
    val packets: List<String>,
)

class DirectRtpFixtureTest {
    private val fixture: DirectRtpFixture by lazy {
        val json = javaClass.getResourceAsStream("/direct-rtp-fixture.json")!!
            .readBytes().decodeToString()
        Json { ignoreUnknownKeys = true }.decodeFromString(DirectRtpFixture.serializer(), json)
    }

    private val b64 = Base64.getDecoder()

    @Test
    fun cryptoLineMatchesFixtureKeyAndSalt() {
        val key = b64.decode(fixture.masterKeyB64)
        val salt = b64.decode(fixture.masterSaltB64)
        assertEquals(16, key.size)
        assertEquals(14, salt.size)
        assertEquals(
            "1 AES_CM_128_HMAC_SHA1_80 inline:" +
                Base64.getEncoder().encodeToString(key + salt),
            fixture.cryptoLine,
        )
    }

    @Test
    fun unprotectsAndReassemblesOriginalAccessUnit() {
        val key = b64.decode(fixture.masterKeyB64)
        val salt = b64.decode(fixture.masterSaltB64)
        val expectedAu = b64.decode(fixture.annexBAuB64)

        SrtpUnprotector(key, salt).use { unprotector ->
            val depacketizer = H264RtpDepacketizer()
            val annexB = ArrayList<ByteArray>()

            var rtpVideo = 0
            var rtcp = 0
            for (packetB64 in fixture.packets) {
                val packet = b64.decode(packetB64)
                val isRtcpMux = (packet[1].toInt() and 0x7F) != 96
                if (isRtcpMux) {
                    rtcp++
                    continue // RTCP SR rides the same UDP port under mux
                }
                rtpVideo++
                val clear = unprotector.unprotect(packet)
                assertNotNull("SRTP unprotect failed for seq=${seqOf(packet)}", clear)
                assertEquals("header is plaintext (SRTP), payload was ciphertext",
                    packet.size - 10, clear!!.size)
                annexB.addAll(depacketizer.push(H264RtpDepacketizer.rtpPayload(clear)))
            }

            assertEquals("expect the FU-A fragments + the single-NAL PPS packet", 3, rtpVideo)
            // RTCP SRs ride the same mux port but are periodic (~5 s) — the
            // capture window may or may not include one; count is informational.

            val reassembled = concat(annexB)
            assertArrayEquals(
                "FU-A + STAP reassembly must reproduce the original Annex-B AU",
                expectedAu, reassembled,
            )
        }
    }

    @Test
    fun depacketizerDropsContinuationAfterLoss() {
        // Start fragment lost: a bare continuation must yield nothing (and
        // not corrupt the next NAL).
        val depacketizer = H264RtpDepacketizer()
        val fakeFuHeader = byteArrayOf(
            0x7C.toByte(), // indicator: F=0 NRI=11 type=28 (FU-A)
            0x00.toByte(), // FU header: S=0 E=0 — pure continuation
            0x01.toByte(), 0x02.toByte(),
        )
        assertEquals(0, depacketizer.push(fakeFuHeader).size)
        depacketizer.reset()
    }

    private fun seqOf(packet: ByteArray) =
        ((packet[2].toInt() and 0xFF) shl 8) or (packet[3].toInt() and 0xFF)

    private fun concat(parts: List<ByteArray>): ByteArray {
        val total = parts.sumOf { it.size }
        val out = ByteArray(total)
        var pos = 0
        for (p in parts) {
            System.arraycopy(p, 0, out, pos, p.size)
            pos += p.size
        }
        return out
    }
}
